import {workspaceHome} from './workspace.js';
import {STATUSES,actions,actionStatus,roleFor} from './workflow.js';
import {api} from './api.js';
import {CATEGORIES,colors,escapeHTML as e,today,shift,startWeek,mins,clock,hours,fresh,conflicts,googleLink,ics} from './model.js';
const root=document.querySelector('#app');const dialog=document.querySelector('#task-dialog');const accountDialog=document.querySelector('#account-dialog');
const state={syncAt:null,syncError:false,readEpoch:0,telegram:null,pics:[],editingPic:null,assignmentPreview:null,report:null,reportFilters:{month:today().slice(0,7),basis:'scheduled',scope:'owned',category:'all',pic:'all'},taskScope:'all',picFilter:'all',profile:null,prefs:{capacity:360,email_enabled:false},deliveries:[],emailConfigured:false,tasks:[],page:'Workspace',filter:'All work',tab:'All',q:'',view:'List',date:today(),users:[],audit:[],userPage:0,hasMore:false,busy:false,editing:null,timer:{id:null,remaining:1500,end:0,running:false}};
const icons={Workspace:'⌘','Assigned to me':'↙','PIC contacts':'♙','Monthly reports':'▤',Overview:'◫','All tasks':'☑',Calendar:'▦','Marketing & follow-up':'↗',Insights:'▥',Settings:'⚙','User management':'♙','Full Time':'▣',Property:'⌂','Web Development':'⌘'};
const icon=s=>`<span class="icon" aria-hidden="true">${icons[s]||s}</span>`;
const act=(action,label,cls='secondary',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const chip=c=>`<span class="chip ${colors[c]||''}">${e(c)}</span>`;
const options=(list,value)=>list.map(x=>`<option value="${e(x)}" ${x===value?'selected':''}>${e(x)}</option>`).join('');
const repeatNames={daily:'Setiap hari',weekdays:'Hari kerja (Senin–Jumat)',weekly:'Mingguan'};
function toast(message,error=false){const node=document.querySelector('#toast');node.textContent=message;node.className='show'+(error?' error':'');clearTimeout(toast.id);toast.id=setTimeout(()=>node.className='',error?9000:6000);}
function syncLabel(){return state.syncError?'● Sinkronisasi tertunda':state.syncAt?'● Sinkron '+state.syncAt.toLocaleTimeString('id-ID',{timeZone:'Asia/Jakarta',hour:'2-digit',minute:'2-digit',second:'2-digit'}):'Menghubungkan…';}
function picConnection(p){return ({verified:'Username cocok · siap menerima tindakan',paired:'Terhubung · username belum diisi',username_mismatch:'Username belum cocok · tindakan diblokir',not_paired:'Menunggu Connect personal',account_required:'Hubungkan akun aktif dahulu'})[p.telegram_status]||'Muat ulang untuk cek koneksi';}
function lockStaleForm(){
 if(!dialog.dataset.stale)return;
 dialog.querySelectorAll('button[type="submit"],form>button.primary,[data-wf]:not([data-wf="history"]),[data-action="delete-task"],[data-action="stop-recurrence"]').forEach(n=>n.disabled=true);
 // The owner form's main submit button has no explicit type.
 dialog.querySelectorAll('.dialog-actions button.primary').forEach(n=>n.disabled=true);
}
let syncing=false;
async function syncTasks(){
 if(syncing||state.busy||!state.profile||document.hidden||!navigator.onLine)return;
 syncing=true;const user=state.profile.id,epoch=state.readEpoch;
 try{
  const tasks=await fetchTasks(api,true);
  // A foreground mutation/load or sign-out wins over an older background response.
  if(state.busy||state.profile?.id!==user||epoch!==state.readEpoch)return;
  const changed=taskSnapshot(tasks)!==taskSnapshot(state.tasks);
  state.tasks=tasks;state.syncAt=new Date();state.syncError=false;
  if(changed){
   if(['Workspace','Overview','All tasks','Assigned to me','Calendar','Marketing & follow-up','Insights'].includes(state.page)){
    const focused=document.activeElement,id=focused?.id,pos=focused?.selectionStart,sidebar=document.querySelector('.side')?.classList.contains('open'),scrollY=window.scrollY;
    render();if(sidebar)document.querySelector('.side')?.classList.add('open');
    if(id&&root.contains(document.getElementById(id))){const n=document.getElementById(id);n.focus({preventScroll:true});try{n.setSelectionRange(pos,pos)}catch{}}
    window.scrollTo(0,scrollY);
   }
   if(dialog.open&&state.editing?.version){
    const current=tasks.find(t=>t.id===state.editing.id);
    if(!current){dialog.close();state.editing=null;toast('Tugas dihapus atau akses Anda berubah.',true);}
    else if(current.version!==state.editing.version){
     dialog.dataset.stale='true';let banner=dialog.querySelector('.stale-notice');
     if(!banner){banner=document.createElement('div');banner.className='stale-notice';banner.setAttribute('role','status');dialog.querySelector('.dialog-header').after(banner);}
     banner.innerHTML=`<strong>Status terbaru: ${e(current.status)}</strong><p>Tugas diperbarui dari perangkat lain/Telegram. Isi formulir Anda tetap disimpan di layar.</p>${act('reload-task','Muat detail terbaru','secondary')}`;
     lockStaleForm();
    }
   }
  }
 }catch(err){
  if(state.profile?.id!==user||epoch!==state.readEpoch)return;
  state.syncError=true;
  if(err.status===401){clearWorkspace();authView('login','Sesi berakhir. Silakan masuk kembali.');}
 }finally{syncing=false;const label=document.querySelector('#sync-status');if(label)label.textContent=syncLabel();}
}
setInterval(()=>void syncTasks(),10000);
window.addEventListener('focus',()=>void syncTasks());
window.addEventListener('online',()=>void syncTasks());
document.addEventListener('visibilitychange',()=>{if(!document.hidden)void syncTasks();});

function overview(){
 const owned=state.tasks.filter(t=>t.user_id===state.profile.id),personal=myWork();
 const day=personal.filter(t=>t.scheduled_date===state.date),open=day.filter(t=>t.status!=='Done');
 const working=state.tasks.filter(t=>t.status==='In progress');
 const review=owned.filter(t=>['Ready for Testing','Testing'].includes(t.status));
 const overdue=state.tasks.filter(t=>t.status!=='Done'&&t.due_date&&t.due_date<today());
 const minutes=day.reduce((sum,t)=>sum+t.duration,0),done=day.filter(t=>t.status==='Done').length;
 const priority=open.filter(t=>t.top_focus).slice(0,3);
 const queue=[...open].sort((a,b)=>Number(b.top_focus)-Number(a.top_focus)||({High:0,Medium:1,Low:2}[a.priority]-{High:0,Medium:1,Low:2}[b.priority]));
 const next=queue.filter(t=>t.start_time).sort((a,b)=>a.start_time.localeCompare(b.start_time));
 const stat=(label,value,detail,kind,tab)=>`<button class="metric-card ${kind}" ${tab?`data-dashboard-tab="${tab}"`:''}><span>${label}</span><strong>${value}</strong><small>${detail}</small></button>`;
 return `<div class="dashboard-toolbar"><div class="date-selector"><input type="date" data-date value="${state.date}" aria-label="Tanggal dashboard"><span>Asia/Jakarta</span></div><div class="button-row"><button class="secondary" data-page="Monthly reports">↓ Laporan bulanan</button><button class="text-button" data-page="Calendar">Lihat kalender ↗</button></div></div>
 <div class="metrics-grid">${stat('Tugas hari ini',open.length,`${done} dari ${day.length} selesai · pekerjaan saya`,'green','Selected day')}${stat('Sedang dikerjakan',working.length,'Pekerjaan saya & PIC','blue','In progress')}${stat('Menunggu review',review.length,'Perlu pemeriksaan Anda','purple','review')}${stat('Lewat deadline',overdue.length,'Prioritaskan tindak lanjut','orange','Overdue')}</div>
 <div class="dashboard-main-grid"><div class="dashboard-primary">
 <section class="panel dashboard-review"><div class="section-heading"><div><span class="eyebrow">REVIEW DESK</span><h2>Perlu keputusan Anda <span class="count">${review.length}</span></h2></div><span class="review-dot">●</span></div>${review.length?review.slice(0,4).map(t=>`<button class="review-item" data-edit="${t.id}"><span class="pic-avatar">${e((t.pic_name||'PIC').slice(0,2).toUpperCase())}</span><span><strong>${e(t.title)}</strong><small>${e(t.pic_name||'Saya')} · ${e(t.status)} · cycle ${t.test_cycle}</small></span><span class="review-link">Review ↗</span></button>`).join(''):'<div class="calm-empty">✓ Tidak ada testing yang menunggu.<small>Ketika PIC memilih Need Testing, tugas muncul di sini.</small></div>'}</section>
 <section class="panel today-panel"><div class="section-heading"><div><span class="eyebrow">MY WORK</span><h2>Rencana hari ini <span class="count">${open.length}</span></h2></div><button class="text-button" data-page="All tasks">Semua tugas ↗</button></div>${priority.length?`<div class="focus-strip">◎ Fokus utama: ${priority.map(t=>`<button data-edit="${t.id}">${e(t.title)}</button><button data-focus="${t.id}" aria-label="Mulai fokus ${e(t.title)}">▷</button>`).join('')}</div>`:''}<div class="task-list">${queue.slice(0,8).map(row).join('')||'<div class="calm-empty">Ruang untuk pekerjaan berikutnya.<small>Tambahkan tugas atau jadwalkan pekerjaan dari All tasks.</small></div>'}</div>${act('new','+ Tambah tugas hari ini','add-row')}</section>
 <section class="panel team-panel"><div class="section-heading"><div><span class="eyebrow">TEAM PROGRESS</span><h2>Progres pekerjaan</h2></div><button class="text-button" data-page="PIC contacts">Kelola PIC ↗</button></div>${working.slice(0,5).map(t=>`<button class="team-progress-row" data-edit="${t.id}"><span class="pic-avatar">${e((t.pic_name||t.owner_name||'SA').slice(0,2).toUpperCase())}</span><span><strong>${e(t.title)}</strong><small>${e(t.pic_name||t.owner_name||'Saya')} · ${e(t.project||t.category)}</small></span><span class="task-status status-in-progress">In progress</span></button>`).join('')||'<div class="calm-empty">Belum ada pekerjaan berstatus In progress.</div>'}</section>
 </div><aside class="dashboard-secondary"><section class="capacity-card"><span class="eyebrow">KAPASITAS PRIBADI</span><h2>${hours(minutes)} <small>/ ${hours(state.prefs.capacity)}</small></h2><progress value="${minutes}" max="${Math.max(minutes,state.prefs.capacity)}"></progress><p>${minutes>state.prefs.capacity?'Melebihi kapasitas '+hours(minutes-state.prefs.capacity)+'. Sesuaikan rencana hari ini.':'Tersisa '+hours(state.prefs.capacity-minutes)+'. Sisakan ruang untuk tugas mendadak.'}</p><div class="area-list">${CATEGORIES.map(c=>`<div><span><i class="dot fill-${colors[c]}"></i>${c}</span><strong>${hours(day.filter(t=>t.category===c).reduce((n,t)=>n+t.duration,0))}</strong></div>`).join('')}</div></section>
 <section class="panel timeline-panel"><div class="section-heading"><h2>Jadwal terencana</h2><button class="text-button" data-page="Calendar">↗</button></div>${next.slice(0,5).map(t=>`<button class="timeline-item" data-edit="${t.id}"><time>${t.start_time.slice(0,5)}</time><span><strong>${e(t.title)}</strong><small>${hours(t.duration)} · ${e(t.category)}</small></span></button>`).join('')||'<p class="helper">Belum ada blok waktu untuk tanggal ini.</p>'}${act('new-time','+ Blok waktu','secondary')}</section>
 <section class="focus-timer"><div class="section-heading"><h2>Focus session</h2><span>25 MIN</span></div><p id="timer-task">${e(personal.find(t=>t.id===state.timer.id)?.title||'Satu tugas pada satu waktu.')}</p><div class="timer-digits" id="timer-digits">25:00</div><div class="timer-actions">${act('timer','▷ Start focus','timer-toggle')}${act('timer-reset','↺','','aria-label="Reset timer"')}</div></section><section class="telegram-health"><span class="eyebrow">TELEGRAM</span><h3>${state.telegram?.account?'Akun pribadi terhubung':'Hubungkan asisten Anda'}</h3><p>Grup menerima pembaruan bersama. PIC dan reviewer menerima tombol pribadi.</p><button class="text-button" data-page="Settings">Kelola integrasi ↗</button></section>
 </aside></div>`;
}
document.addEventListener('click',event=>{const n=event.target.closest('[data-dashboard-tab]');if(!n||state.busy)return;state.page='All tasks';state.filter='All work';state.taskScope='all';state.picFilter='all';state.q='';state.tab=n.dataset.dashboardTab;if(state.tab==='Selected day')state.taskScope='personal';if(state.tab==='review'){state.tab='Review';state.taskScope='owned';}render();});
async function work(fn){if(state.busy)return;state.busy=true;document.body.setAttribute('aria-busy','true');document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn()}catch(err){toast(err.message,true);if(err.status===401){clearWorkspace();authView('login',err.status===401?'Sesi berakhir. Silakan masuk kembali.':err.message)}}finally{state.busy=false;document.body.removeAttribute('aria-busy');document.querySelectorAll('button').forEach(b=>b.disabled=false);if(document.querySelector('#task-form'))updateRepeatUI();lockStaleForm();}}
function clearWorkspace(){state.readEpoch++;state.syncAt=null;state.profile=null;state.telegram=null;state.tasks=[];state.pics=[];state.report=null;state.assignmentPreview=null;state.editing=null;state.editingPic=null;document.querySelector('#print-report')?.remove();state.users=[];state.audit=[];state.deliveries=[];state.prefs={capacity:360,email_enabled:false};state.timer={id:null,remaining:1500,end:0,running:false};dialog.close();accountDialog.close();}
async function loadTasks(){const epoch=++state.readEpoch,all=await fetchTasks(api);if(epoch!==state.readEpoch)return;state.tasks=all;state.syncAt=new Date();state.syncError=false;}
async function load(){const d=await api('profile');state.profile=d.profile;state.prefs=d.preferences;state.deliveries=d.deliveries;state.emailConfigured=d.emailConfigured;await loadTasks();await loadPics();state.telegram=await api('telegram');const linked=['Workspace','Overview','All tasks','Calendar','Settings'].find(p=>'#'+p.toLowerCase().replaceAll(' ','-')===location.hash);if(linked)state.page=linked;render();}
async function loadUsers(){const d=await api('users?page='+state.userPage);state.users=d.users;state.audit=d.audit;state.hasMore=d.hasMore;}
function authView(mode='login',message=''){root.innerHTML=`<div class="auth-shell"><section class="auth-story"><div class="brand"><span class="logo-mark">f.</span>focusdesk.</div><h1>Make room<br>for what matters.</h1><p>Satu ruang untuk pekerjaan tetap, project freelance, dan tindak lanjut yang tidak boleh terlewat.</p><div class="sidebar-note"><span>FULL TIME · PROPERTY · WEB DEVELOPMENT</span></div></section><section class="auth-panel"><div class="auth-card"><p class="eyebrow">YOUR PERSONAL WORKSPACE</p><h2>${mode==='login'?'Welcome back.':mode==='recover'?'Reset your password.':'Set your password.'}</h2><p class="muted">${mode==='login'?'Masuk untuk melanjutkan rencana Anda.':mode==='recover'?'Kami akan mengirim instruksi ke email akun Anda.':'Buat password pribadi untuk mengakses workspace.'}</p>${message?`<div class="auth-error">${e(message)}</div>`:''}<form id="auth-form" data-mode="${mode}" class="form-stack">${mode!=='password'?'<label>Email<input type="email" name="email" autocomplete="email" maxlength="254" required></label>':''}${mode!=='recover'?`<label>Password<input type="password" name="password" autocomplete="${mode==='login'?'current-password':'new-password'}" ${mode==='password'?'minlength="12" maxlength="128"':''} required></label>`:''}${mode==='password'?'<label>Confirm password<input type="password" name="confirm" autocomplete="new-password" minlength="12" maxlength="128" required></label>':''}<button class="primary" type="submit">${mode==='login'?'Sign in':mode==='recover'?'Send reset instructions':'Save password'}</button></form><div class="auth-footer">${mode==='login'?act('forgot','Forgot password?','text-button'):act('back-login','Back to sign in','text-button')}</div><p class="helper login-help">Pendaftaran melalui undangan admin. Akun baru tidak otomatis mendapatkan akses.</p><p class="auth-footer">Focusdesk v1.6 · Asia/Jakarta</p></div></section></div>`;}
function render(){if(!state.profile)return authView();const name=state.profile.display_name||state.profile.email.split('@')[0];const nav=['Workspace','Overview','All tasks','Assigned to me','Calendar','Marketing & follow-up','PIC contacts','Monthly reports','Insights',...(state.profile.role==='admin'?['User management']:[])];root.innerHTML=`<div class="app-shell"><aside class="side"><button class="mobile-close icon-button" data-action="sidebar" aria-label="Tutup navigasi">×</button><div class="brand"><span class="logo-mark">f.</span>focusdesk.</div><div class="workspace"><div class="avatar">${e(name.slice(0,2).toUpperCase())}</div><div><strong>Focusdesk workspace</strong><span>${state.profile.role==='admin'?'Administrator':'Member'}</span></div></div><p class="nav-label">WORKSPACE</p>${nav.map(n=>`${n==='PIC contacts'?'<p class="nav-label">KELOLA & LAPORAN</p>':''}<button class="nav-item ${state.page===n?'active':''}" data-page="${n}">${icon(n)}<span>${n}</span></button>`).join('')}<p class="nav-label">KNOWLEDGE & SUPPORT</p><a class="nav-item" href="/desk.html">▤ Knowledge Desk</a>${state.profile.role==='admin'?'<a class="nav-item" href="/desk.html#ai">✧ AI & Telegram</a>':''}<p class="nav-label category-label">MY WORK AREAS</p>${CATEGORIES.map(c=>`<button class="nav-item ${state.filter===c&&state.page==='All tasks'?'active':''}" data-category="${c}">${icon(c)}<span>${c}</span><small>${state.tasks.filter(t=>t.category===c&&t.status!=='Done').length}</small></button>`).join('')}<div class="sidebar-note"><span>◦ A little reminder</span><p>Semua bisa dicatat.<br>Tidak semua harus<br>dikerjakan hari ini.</p></div><div class="side-bottom"><button class="nav-item ${state.page==='Settings'?'active':''}" data-page="Settings">${icon('Settings')}Settings & integrations</button><div class="profile"><div class="avatar dark">${e(name.slice(0,2).toUpperCase())}</div><div><strong>${e(name)}</strong><span>${e(state.profile.role)}</span></div><button class="icon-button" data-action="logout" aria-label="Keluar" title="Sign out">⇥</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="icon-button sidebar-toggle" data-action="sidebar" aria-label="Buka navigasi">☰</button><span>My workspace</span> › <strong>${state.page}</strong></div><div class="top-actions"><span id="sync-status" class="connection" role="status">${syncLabel()}</span><span class="timezone">WIB / Jakarta</span>${act('refresh','↻','icon-button','aria-label="Muat ulang data"')}</div></header><div class="content"><div class="page-heading"><div><div class="eyebrow">${state.page==='Overview'?'YOUR DAY, AT A GLANCE':'YOUR PERSONAL WORKSPACE'}</div><h1>${state.page==='Overview'?'Dashboard pekerjaan':state.page}</h1><p>${({Workspace:'Pilih area kerja, akses panduan, dan hubungkan tim Anda.',Overview:'Pantau pekerjaan Anda, progres tim, dan tugas yang menunggu review.','All tasks':'Rapikan pekerjaan, tentukan prioritas, lalu beri ruang di kalender.',Calendar:'Jadwalkan waktu pengerjaan sebelum deadline mendekat.','Marketing & follow-up':'Jaga percakapan tetap berjalan, dari prospek sampai project.',Insights:'Pahami beban pekerjaan dari rencana dan progres Anda.',Settings:'Kelola akun, kapasitas harian, dan ringkasan email.','User management':'Kelola akses akun. Tugas dibagikan hanya melalui penugasan PIC.','Assigned to me':'Tugas yang diberikan kepada Anda. Perbarui status dan catatan progres.','PIC contacts':'Kelola PIC, username Telegram, dan kesiapan menerima tugas.','Monthly reports':'Laporan bulanan berdasarkan tanggal pengerjaan, deadline, atau penyelesaian.'})[state.page]}</p></div>${state.page==='User management'?act('invite','+ Invite user','primary'):state.page==='PIC contacts'?act('new-pic','+ New PIC','primary'):state.page==='Monthly reports'?'':act('new','+ New task','primary')}</div>${pageContent()}<footer class="page-footer"><span>focusdesk. <i>A little more clarity, every day.</i></span><span>Data pribadi · Supabase · Asia/Jakarta</span></footer></div></main></div>`;updateTimer();}
function row(t){return`<div class="task-row ${t.status==='Done'?'completed':''}"><input type="checkbox" ${t.status==='Done'?'checked':''} data-complete="${t.id}" ${!roleFor(t,state.profile.id).executor?'disabled':''} aria-label="Selesaikan ${e(t.title)}"><button class="task-title" data-edit="${t.id}"><strong>${e(t.title)}${t.recurrence_pattern?` <span class="repeat-badge">↻ ${e(repeatNames[t.recurrence_pattern])}</span>`:''}</strong><span class="${t.due_date&&t.due_date<today()&&t.status!=='Done'?'due-text':''}">${e(t.status)}${t.requires_testing?' · Review required':''} · ${e(t.project||'Tanpa project')} · PIC: ${e(t.pic_name||t.owner_name||'Saya')}${t.user_id!==state.profile.id?' · Ditugaskan kepada saya':''} · ${t.start_time?.slice(0,5)||'Fleksibel'} · ${hours(t.duration)}${t.due_date?' · Due '+t.due_date:''}</span></button><span class="task-status status-${t.status.toLowerCase().replaceAll(' ','-')}">${e(t.status)}</span>${chip(t.category)}<span class="priority ${t.priority.toLowerCase()}">${t.priority==='High'?'↑ ':''}${t.priority}</span><button class="icon-button" data-edit="${t.id}" aria-label="Edit ${e(t.title)}">⋯</button></div>`;}
function pageContent(){if(state.page==='Workspace')return workspaceHome(state);if(state.page==='Overview')return overview();if(['All tasks','Assigned to me','Marketing & follow-up'].includes(state.page))return tasksPage();if(state.page==='PIC contacts')return picsPage();if(state.page==='Monthly reports')return reportsPage();if(state.page==='Calendar')return calendar();if(state.page==='Insights')return insights();if(state.page==='Settings')return settings();if(state.page==='User management')return users();return'';}

function filtered(){return state.tasks.filter(t=>(state.page!=='Assigned to me'||(t.assignee_id===state.profile.id&&t.user_id!==state.profile.id))&&(state.taskScope==='all'||(state.taskScope==='personal'?myWork().some(x=>x.id===t.id):state.taskScope==='owned'?t.user_id===state.profile.id:t.assignee_id===state.profile.id&&t.user_id!==state.profile.id))&&(state.picFilter==='all'||(state.picFilter==='self'?!t.pic_id:t.pic_id===state.picFilter))&&(state.filter==='All work'||t.category===state.filter)&&(!state.q||[t.title,t.project,t.notes].join(' ').toLowerCase().includes(state.q.toLowerCase()))&&(state.page!=='Marketing & follow-up'||['Marketing','Follow-up'].includes(t.kind))&&(state.tab==='All'||(state.tab==='Today'?t.scheduled_date===today():state.tab==='Selected day'?t.scheduled_date===state.date:state.tab==='Review'?['Ready for Testing','Testing'].includes(t.status):state.tab==='Overdue'?t.due_date&&t.due_date<today()&&t.status!=='Done':t.status===state.tab)));}
function tasksPage(){const list=filtered();return`<div class="filter-bar"><label class="search-box">⌕ <input id="search" type="search" placeholder="Cari tugas atau project…" value="${e(state.q)}" aria-label="Cari tugas"></label><select id="category-filter" aria-label="Kategori">${options(['All work',...CATEGORIES],state.filter)}</select><select id="scope-filter" aria-label="Lingkup tugas">${[['all','Semua akses'],['owned','Saya kelola'],['assigned','Ditugaskan ke saya']].map(([v,l])=>`<option value="${v}" ${state.taskScope===v?'selected':''}>${l}</option>`).join('')}</select><select id="pic-filter" aria-label="Filter PIC">${picOptions(state.picFilter)}</select><select id="view-filter" aria-label="Tampilan">${options(['List','Board'],state.view)}</select></div><div class="task-tabs">${['All','Today','Overdue',...STATUSES].map(s=>`<button data-tab="${s}" class="${s===state.tab?'active':''}">${s}</button>`).join('')}</div>${state.view==='List'?`<div class="panel all-task-list">${list.map(row).join('')||'<div class="empty">Tidak ada tugas dengan filter ini.</div>'}</div>`:`<div class="board">${STATUSES.map(s=>`<section><h2>${s} <span class="count">${list.filter(t=>t.status===s).length}</span></h2>${list.filter(t=>t.status===s).map(t=>`<button class="board-card" data-edit="${t.id}">${chip(t.category)}<strong>${e(t.title)}</strong><span>${e(t.project)} · PIC: ${e(t.pic_name||t.owner_name||'Saya')}</span><div><span class="priority ${t.priority.toLowerCase()}">${t.priority}</span><small>${t.due_date||'Fleksibel'}</small></div></button>`).join('')}</section>`).join('')}</div>`}`;}
function calendar(){const week=startWeek(state.date);return`<div class="filter-bar"><div class="calendar-navigation">${act('prev-week','‹','icon-button','aria-label="Minggu sebelumnya"')}${act('today','Today')}${act('next-week','›','icon-button','aria-label="Minggu berikutnya"')}<input class="date-input" data-date type="date" value="${state.date}" aria-label="Tanggal kalender"></div>${act('export','↓ Export calendar')}</div><div class="calendar-grid">${Array.from({length:7},(_,i)=>shift(week,i)).map(d=>`<section class="${d===today()?'current-day':''}"><header><span>${new Date(d+'T12:00:00Z').toLocaleDateString('en',{weekday:'short'})}</span><strong>${Number(d.slice(-2))}</strong><small>${hours(state.tasks.filter(t=>t.scheduled_date===d).reduce((a,t)=>a+t.duration,0))}</small></header>${state.tasks.filter(t=>t.scheduled_date===d).sort((a,b)=>(a.start_time||'99').localeCompare(b.start_time||'99')).map(t=>`<button class="calendar-task ${colors[t.category]} ${t.status==='Done'?'is-done':''}" data-edit="${t.id}"><span>${t.start_time?.slice(0,5)||'Fleksibel'} · ${hours(t.duration)}</span><strong>${e(t.title)}</strong><small>${t.category}${conflicts(t,state.tasks).length?' · ⚠ Bentrok':''}</small></button>`).join('')}<button class="calendar-add" data-newday="${d}" aria-label="Tambah tugas ${d}">+</button></section>`).join('')}</div><p class="helper">Jadwal semua tugas yang Anda kelola atau terima. Bentrok dihitung per pelaksana. Waktu Asia/Jakarta. Ekspor .ics dan Add to Google Calendar bersifat manual; perubahan tidak tersinkron otomatis.</p>`;}
function insights(){const week=startWeek(state.date);return`<div class="insights-grid"><section class="panel"><h2>Planned hours · this week</h2><p class="helper">Minggu ${week}. Estimasi pekerjaan pribadi dan penugasan masuk; bukan jam kerja aktual.</p><div class="bar-chart">${Array.from({length:7},(_,i)=>shift(week,i)).map(d=>{const n=myWork().filter(t=>t.scheduled_date===d).reduce((a,t)=>a+t.duration,0);return`<div><strong>${hours(n)}</strong><div class="bar-track"><div style="height:${Math.min(100,n/720*100)}%"></div></div><span>${new Date(d+'T12:00:00Z').toLocaleDateString('en',{weekday:'short'})}</span></div>`}).join('')}</div></section><section class="panel"><h2>Work areas</h2>${CATEGORIES.map(c=>{const all=state.tasks.filter(t=>t.category===c);const done=all.filter(t=>t.status==='Done').length;return`<div class="area-progress"><div class="area-line">${chip(c)}<span>${done} / ${all.length} selesai</span></div><progress value="${done}" max="${all.length||1}" style="width:100%"></progress></div>`}).join('')}<p class="helper">Progres seluruh tugas yang dapat Anda akses.</p></section><section class="panel"><h2>Focus recommendations</h2>${[['01','Protect your full-time hours','Kelompokkan tugas System Analyst pada jam kerja; jadwalkan freelance sesuai kapasitas.'],['02','Batch marketing & follow-ups','Kumpulkan tugas sejenis dalam satu sesi agar tidak berpindah konteks setiap ada pesan.'],['03','Leave room for the unexpected','Sisakan ruang untuk rapat, jeda, dan permintaan mendadak.']].map(([n,h,p])=>`<div class="recommendation"><span>${n}</span><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</section><section class="panel"><h2>Delivery snapshot</h2><div class="big-stat">${state.tasks.filter(t=>t.status==='Done').length}<span>tugas selesai dari ${state.tasks.length}</span></div><p class="muted">${state.tasks.filter(t=>t.kind==='Follow-up'&&t.status!=='Done').length} follow-up terbuka.</p></section></div>`;}
function settings(){return`<div class="settings-grid">${telegramPanel()}<section class="panel"><h2>Personal preferences</h2><form id="preferences-form" class="form-stack"><label>Nama panggilan<input name="display_name" value="${e(state.profile.display_name||'')}" maxlength="80" required></label><label>Email akun<input class="readonly" readonly value="${e(state.profile.email)}"></label><label>Kapasitas harian (menit)<input type="number" name="capacity" min="30" max="1440" step="30" value="${state.prefs.capacity}" required></label><label class="checkbox-label"><input type="checkbox" name="email_enabled" ${state.prefs.email_enabled?'checked':''}> Aktifkan daily email briefing</label><p class="helper">Target 08.00 WIB. Pada Vercel Hobby, pengiriman bisa berlangsung dalam jam 08.00–08.59 WIB. Kapasitas mencakup seluruh kategori.</p><button class="primary">Save preferences</button></form></section><section class="panel"><h2>✉ Daily email briefing</h2><span class="status-pill ${state.emailConfigured?'':'off'}">${state.emailConfigured?'Konfigurasi email terdeteksi':'Email belum dikonfigurasi'}</span><p class="helper">Berisi prioritas, jadwal, dan tugas terlambat. Penerima adalah email akun yang terverifikasi. Satu briefing per hari, termasuk pengiriman manual.</p>${act('send-digest','Send today’s briefing','secondary')}<div class="setup-notice"><strong>Status terakhir</strong>${state.deliveries.length?state.deliveries.map(d=>`<p>${d.day}: ${e(d.status)}${d.accepted_at?' · '+new Date(d.accepted_at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'}):''}</p>`).join(''):'Belum ada pengiriman.'}<p>Accepted berarti diterima penyedia email, bukan konfirmasi masuk inbox.</p></div></section><section class="panel"><h2>Account & security</h2><p class="muted">Role: <strong>${state.profile.role}</strong>. Tugas milik Anda dibagikan hanya kepada akun PIC yang dipilih. PIC dapat mengubah status dan catatan progres, tanpa menghapus atau mengubah rencana tugas.</p><h3>Change password</h3><form id="password-form" class="form-stack"><label>Password baru<input type="password" name="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><label>Konfirmasi password<input type="password" name="confirm" minlength="12" maxlength="128" autocomplete="new-password" required></label><button class="secondary">Update password</button></form><p class="helper">Gunakan password unik minimal 12 karakter.</p>${act('logout','Sign out','text-button')}</section><section class="panel"><h2>▦ Google Calendar</h2><span class="chip">Manual export</span><p class="helper">Unduh file kalender atau buka tugas lalu pilih Add to Google Calendar. Sinkronisasi otomatis belum tersedia.</p>${act('export','↓ Download calendar (.ics)')}<h3>Application guide</h3><p class="helper">Panduan deployment dan User Guide tersedia di folder docs dalam paket ZIP. Tugas akun baru dimulai kosong; data contoh lama tidak diimpor otomatis.</p></section></div>`;}
function users(){return`<section class="panel"><div class="section-heading"><h2>Workspace members</h2><span class="muted">Admin & user · undangan pribadi</span></div><div class="user-table-wrap"><table class="user-table"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody>${state.users.map(p=>`<tr><td><strong>${e(p.display_name||'Belum mengisi nama')}</strong><small>${e(p.email)}</small></td><td>${p.role}${p.id===state.profile.id?' (Anda)':''}</td><td><span class="status-pill ${p.is_active?'':'off'}">${p.is_active?'Active':'Inactive'}</span></td><td><div class="user-actions">${p.id!==state.profile.id?`<button class="secondary" data-manage="${p.id}">Manage</button><button class="text-button" data-resetuser="${p.id}">Reset password</button>`:'Akun sendiri'}</div></td></tr>`).join('')}</tbody></table></div><div class="pager">${state.userPage?act('users-prev','‹ Previous'):''}<span>Halaman ${state.userPage+1}</span>${state.hasMore?act('users-next','Next ›'):''}</div><p class="helper">Tidak ada penghapusan permanen. Nonaktifkan akun untuk menghentikan akses tanpa menghapus tugas. Akun sendiri tidak dapat dinonaktifkan atau diturunkan rolenya lewat aplikasi.</p></section><section class="panel" style="margin-top:22px"><h2>Recent access changes</h2><div class="audit-list">${state.audit.map(a=>`<p>${new Date(a.created_at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})} · ${e(a.action)} · target ${e(a.target_id)} · ${e(a.details.role)} / ${a.details.is_active?'active':'inactive'}</p>`).join('')||'<p>Belum ada perubahan akses.</p>'}</div></section>`;}
function openTask(t){delete dialog.dataset.stale;state.editing={...t};if(t.version&&t.user_id!==state.profile.id)return openAssignedTask(t);const field=(label,name,type='text',extra='')=>`<label>${label}<input type="${type}" name="${name}" value="${e(t[name]??'')}" ${extra}></label>`;const sel=(label,name,list)=>`<label>${label}<select name="${name}">${options(list,t[name])}</select></label>`;const repeat=t.version?(t.recurrence_id?`<div class="recurring-info"><div><strong>↻ ${e(repeatNames[t.recurrence_pattern])}</strong><span>Occurrence ${e(t.recurrence_date)} · perubahan hanya berlaku pada tanggal ini.</span></div>${act('stop-recurrence','Stop repeating','secondary')}</div>`:''):`<fieldset class="repeat-controls"><legend>Repeat task</legend><div class="form-three"><label>Repeat<select name="repeat_pattern" id="repeat-pattern"><option value="once">Tidak berulang</option><option value="daily">Setiap hari</option><option value="weekdays">Hari kerja (Senin–Jumat)</option><option value="weekly">Mingguan</option></select></label><label id="repeat-interval-wrap">Setiap<input type="number" id="repeat-interval" name="repeat_interval" min="1" max="30" value="1"><span id="repeat-unit" class="field-suffix">hari</span></label><label id="repeat-end-wrap">Berakhir (opsional)<input type="date" name="repeat_end_date" min="${e(t.scheduled_date||today())}"></label></div><p id="repeat-help" class="helper">Pilih pola untuk membuat checklist terpisah pada setiap tanggal.</p></fieldset>`;dialog.innerHTML=`<div class="dialog-header"><h2>${t.version?'Task details':'Make a little room.'}</h2><button class="icon-button" data-action="close-task" aria-label="Tutup">×</button></div><p class="muted">Tentukan hasil, prioritas, dan waktu yang diperlukan.</p><form id="task-form" class="form-stack">${repeat}${testingFields(t)}${field('Task name','title','text','required maxlength="180" autofocus')}<div class="form-two">${sel('Work area','category',CATEGORIES)}${field('Project','project','text','maxlength="100"')}</div><div class="form-three">${sel('Priority','priority',['High','Medium','Low'])}${sel('Status','status',t.requires_testing?[t.status]:['Backlog','To do','In progress','Done'])}${sel('Task type','kind',['Delivery','Meeting','Marketing','Follow-up'])}</div><div class="form-two">${field('Deadline','due_date','date')}${field('Scheduled day','scheduled_date','date')}</div><div class="form-two">${field('Start time (WIB)','start_time','time')}${field('Duration (minutes)','duration','number','min="5" max="720" step="5" required')}</div><div class="form-two"><label>PIC pengerjaan<select name="pic_id" id="task-pic"><option value="">Saya / pemilik tugas</option>${state.pics.filter(p=>p.is_active||p.id===t.pic_id).map(p=>`<option value="${p.id}" ${p.id===t.pic_id?'selected':''}>${e(p.name)}${p.is_active?'':' (nonaktif)'}</option>`).join('')}</select></label><div class="pic-hint" id="pic-hint"></div></div><p class="helper">Akun PIC yang terhubung mendapat akses setiap occurrence saat dibuat. Email penugasan tetap dikirim manual per occurrence untuk mencegah spam.</p><label>Notes<textarea name="notes" rows="3" maxlength="4000">${e(t.notes)}</textarea></label><label>Catatan progres<textarea name="progress_note" rows="2" maxlength="4000">${e(t.progress_note||'')}</textarea></label><label class="checkbox-label"><input id="top-focus" type="checkbox" name="top_focus" ${t.top_focus?'checked':''}> Include in top 3 priorities</label><p id="conflict-message" class="conflict-warning" hidden></p><div class="dialog-actions">${t.version?act('delete-task','Delete','text-button danger'):''}${t.scheduled_date?`<a class="text-button" target="_blank" rel="noopener noreferrer" href="${e(googleLink(t))}">Add to Google Calendar ↗</a>`:''}<button id="save-email" class="secondary" type="submit" name="intent" value="email">Save & review email</button><button class="primary" type="submit">Save task</button></div>${workflowPanel(t)}<p class="helper">Tautan kalender menggunakan data terakhir saat detail dibuka. Simpan perubahan sebelum mengekspor.</p></form>`;dialog.showModal();updatePicHint();updateRepeatUI();checkConflicts();}
function taskFromForm(){const f=new FormData(document.querySelector('#task-form'));const repeat=f.get('repeat_pattern')||'once';return{...state.editing,...Object.fromEntries(f),requires_testing:state.editing.requires_testing===true||f.has('requires_testing'),acceptance_criteria:f.get('acceptance_criteria')||'',telegram_group_id:f.get('telegram_group_id')||null,duration:Number(f.get('duration')),top_focus:repeat==='once'&&f.has('top_focus'),repeat_pattern:repeat,repeat_interval:Number(f.get('repeat_interval')||1),repeat_end_date:f.get('repeat_end_date')||null,pic_id:f.get('pic_id')||null,assignee_id:state.pics.find(p=>p.id===f.get('pic_id'))?.linked_user_id||null,pic_email:state.pics.find(p=>p.id===f.get('pic_id'))?.email||null,user_id:state.profile.id,start_time:f.get('start_time')?.slice(0,5)||null,due_date:f.get('due_date')||null,scheduled_date:f.get('scheduled_date')||null};}
function updateRepeatUI(){const pattern=document.querySelector('#repeat-pattern')?.value||'once';const recurring=pattern!=='once';for(const id of ['repeat-interval-wrap','repeat-end-wrap']){const n=document.querySelector('#'+id);if(n)n.hidden=!recurring}const unit=document.querySelector('#repeat-unit');if(unit)unit.textContent=pattern==='weekly'?'minggu':pattern==='weekdays'?'minggu kerja':'hari';const help=document.querySelector('#repeat-help');if(help)help.textContent=recurring?'Setiap tanggal menjadi checklist mandiri. Sistem menyiapkan jadwal hingga 14 hari ke depan.':'Pilih pola untuk membuat checklist terpisah pada setiap tanggal.';const status=document.querySelector('[name="status"]');if(recurring&&status)status.value='To do';const focus=document.querySelector('#top-focus');if(focus){if(recurring)focus.checked=false;focus.disabled=recurring}const email=document.querySelector('#save-email');if(email){email.disabled=recurring;email.title=recurring?'Simpan seri dahulu; email dapat dikirim dari occurrence tertentu.':''}}
function checkConflicts(){const t=taskFromForm();const c=conflicts(t,state.tasks);const node=document.querySelector('#conflict-message');node.hidden=!c.length;node.textContent=c.length?'Bentrok dengan: '+c.map(t=>t.title).join(', '):'';}
function openInvite(){accountDialog.innerHTML=`<div class="dialog-header"><h2>Invite a new user</h2>${act('close-account','×','icon-button','aria-label="Tutup"')}</div><p class="helper">Undangan dikirim lewat email. Pengguna baru mendapatkan role user dan workspace kosong.</p><form id="invite-form" class="form-stack"><label>Nama<input name="display_name" maxlength="80" required></label><label>Email<input name="email" type="email" maxlength="254" required></label><button class="primary">Send invitation</button></form>`;accountDialog.showModal();}
function openManage(id){const p=state.users.find(p=>p.id===id);if(!p)return;accountDialog.innerHTML=`<div class="dialog-header"><h2>Manage access</h2>${act('close-account','×','icon-button','aria-label="Tutup"')}</div><p class="helper">${e(p.email)}</p><form id="access-form" data-id="${id}" class="form-stack"><label>Role<select name="role">${options(['user','admin'],p.role)}</select></label><label class="checkbox-label"><input name="is_active" type="checkbox" ${p.is_active?'checked':''}> Akun aktif</label><p class="helper">Admin dapat mengundang dan mengelola pengguna lain. Nonaktif menghentikan akses data, termasuk dari sesi yang sudah login.</p><button class="primary">Save access</button></form>`;accountDialog.showModal();}
function updateTimer(){const t=state.timer;if(t.running){t.remaining=Math.max(0,Math.ceil((t.end-Date.now())/1000));if(!t.remaining){t.running=false;toast('Sesi fokus selesai. Ambil jeda, lalu perbarui status tugas.')}}const d=document.querySelector('#timer-digits');if(d)d.textContent=String(Math.floor(t.remaining/60)).padStart(2,'0')+':'+String(t.remaining%60).padStart(2,'0');const b=document.querySelector('.timer-toggle');if(b)b.textContent=t.running?'Ⅱ Pause focus':'▷ Start focus';}
setInterval(updateTimer,1000);
function exportCalendar(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([ics(state.tasks)],{type:'text/calendar;charset=utf-8'}));a.download='focusdesk-calendar.ics';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Kalender diunduh. Impor manual ke Google Calendar.');}
async function navigate(page){if(page==='PIC contacts')await loadPics();state.page=page;history.replaceState(null,'','#'+encodeURIComponent(page.toLowerCase().replaceAll(' ','-')));state.q='';state.filter='All work';state.tab='All';if(page==='Settings')state.telegram=await api('telegram');if(page==='User management')await loadUsers();if(page==='Monthly reports')await loadReport();state.taskScope='all';state.picFilter='all';render();}
document.addEventListener('click',event=>{const n=event.target.closest('button,[data-edit],[data-day]');if(!n||n.disabled)return;if(n.dataset.page)return void work(()=>navigate(n.dataset.page));if(n.dataset.category){state.filter=n.dataset.category;state.page='All tasks';state.tab='All';return render()}if(n.dataset.edit){const t=state.tasks.find(t=>t.id===n.dataset.edit);if(t)openTask({...t,start_time:t.start_time?.slice(0,5)||''});return}if(n.dataset.tab){state.tab=n.dataset.tab;return render()}if(n.dataset.day){state.date=n.dataset.day;return render()}if(n.dataset.newday)return openTask(fresh(n.dataset.newday));if(n.dataset.focus){state.timer={id:n.dataset.focus,remaining:1500,end:Date.now()+1500000,running:true};return render()}if(n.dataset.editpic)return openPic(state.pics.find(p=>p.id===n.dataset.editpic));if(n.dataset.manage)return openManage(n.dataset.manage);if(n.dataset.resetuser)return void work(async()=>{const p=state.users.find(p=>p.id===n.dataset.resetuser);if(confirm('Kirim instruksi reset password ke '+p.email+'?'))toast((await api('users',{method:'POST',body:{action:'reset',id:p.id}})).message)});
 const a=n.dataset.action;if(!a)return;
 if(a==='reload-task'){const t=state.tasks.find(t=>t.id===state.editing?.id);if(t&&confirm('Muat data terbaru? Perubahan formulir yang belum disimpan akan diganti.'))openTask(t);return}if(a==='sidebar'){document.querySelector('.side')?.classList.toggle('open');return}if(a==='close-task')return dialog.close();if(a==='close-account')return accountDialog.close();if(a==='forgot')return authView('recover');if(a==='back-login')return authView();if(a==='new')return openTask(fresh(state.date));if(a==='new-focus')return openTask({...fresh(state.date),top_focus:true});if(a==='new-time')return openTask({...fresh(state.date),start_time:'09:00'});if(a==='invite')return openInvite();if(a==='new-pic')return openPic();if(a==='report-print')return printReport();if(a==='export')return exportCalendar();if(a==='today'){state.date=today();return render()}if(a==='prev-week'||a==='next-week'){state.date=shift(state.date,a==='prev-week'?-7:7);return render()}if(a==='overdue'){state.page='All tasks';state.tab='Overdue';return render()}if(a==='timer'){const t=state.timer;if(t.running){updateTimer();t.running=false}else{t.remaining=t.remaining||1500;t.end=Date.now()+t.remaining*1000;t.running=true}return updateTimer()}if(a==='timer-reset'){state.timer.running=false;state.timer.remaining=1500;return updateTimer()}
 void work(async()=>{if(a==='delegated'){state.page='All tasks';state.taskScope='owned';render()}if(a==='assignment-send')await sendAssignment();if(a==='report-xlsx'||a==='report-csv')await downloadReport(a==='report-xlsx'?'xlsx':'csv');if(a==='refresh'){await load();if(state.page==='Monthly reports'){await loadReport();render();}if(state.page==='User management'){await loadUsers();render()}toast('Data terbaru dimuat')}if(a==='logout'){await api('auth',{method:'POST',body:{action:'logout'}});clearWorkspace();authView()}if(a==='delete-task'&&confirm('Hapus tugas ini? Event Google Calendar yang sudah diekspor tidak ikut dihapus.')){await api('tasks',{method:'DELETE',body:{id:state.editing.id,version:state.editing.version}});dialog.close();await loadTasks();render();toast('Tugas dihapus')}if(a==='stop-recurrence'&&confirm('Hentikan seri ini? Tugas setelah occurrence ini yang belum Done akan dihapus. Riwayat selesai tetap disimpan.')){const result=await api('tasks',{method:'PATCH',body:{id:state.editing.id,version:state.editing.version,action:'stop-recurrence'}});dialog.close();await loadTasks();render();toast(result.message)}if(a==='send-digest'&&confirm('Kirim briefing hari ini ke '+state.profile.email+'?')){toast((await api('digest',{method:'POST',body:{}})).message);await load()}if(a==='users-prev'||a==='users-next'){state.userPage=Math.max(0,state.userPage+(a==='users-prev'?-1:1));await loadUsers();render()}});
});
document.addEventListener('change',event=>{const n=event.target;if(n.dataset.complete){const t=state.tasks.find(t=>t.id===n.dataset.complete);if(t.requires_testing||!roleFor(t,state.profile.id).executor){n.checked=t.status==='Done';openTask(t);return}if(state.busy){n.checked=t.status==='Done';return}void work(async()=>{try{await api('tasks',{method:'PATCH',body:{id:t.id,version:t.version,action:'progress',status:n.checked?'Done':'To do',progress_note:t.progress_note||''}});await loadTasks();render()}catch(err){n.checked=t.status==='Done';throw err}});return}if(n.hasAttribute('data-date')){state.date=n.value||today();return render()}if(n.id==='category-filter'){state.filter=n.value;return render()}if(n.id==='scope-filter'){state.taskScope=n.value;return render()}if(n.id==='pic-filter'){state.picFilter=n.value;return render()}if(n.id==='task-pic')updatePicHint();if(n.id==='repeat-pattern'||n.id==='repeat-interval')updateRepeatUI();if(n.id==='view-filter'){state.view=n.value;return render()}if(n.closest('#task-form'))checkConflicts();});
document.addEventListener('input',event=>{if(event.target.id==='search'){const p=event.target.selectionStart;state.q=event.target.value;render();const n=document.querySelector('#search');n.focus();try{n.setSelectionRange(p,p)}catch{}}});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;const f=new FormData(form);void work(async()=>{
 if(form.id==='auth-form'){const mode=form.dataset.mode;if(mode==='login'){await api('auth',{method:'POST',body:{action:'login',email:f.get('email'),password:f.get('password')}});await load();const requested=new URLSearchParams(location.search).get('task');if(requested){const t=state.tasks.find(t=>t.id===requested);if(t)openTask(t);else toast('Tugas tidak tersedia untuk akun ini.',true);}}if(mode==='recover'){const d=await api('auth',{method:'POST',body:{action:'recover',email:f.get('email')}});toast(d.message)}if(mode==='password'){if(f.get('password')!==f.get('confirm'))throw Error('Konfirmasi password tidak sama');await api('auth',{method:'POST',body:{action:'password',password:f.get('password')}});history.replaceState(null,'',location.pathname);toast('Password tersimpan. Silakan masuk.');await api('auth',{method:'POST',body:{action:'logout'}});clearWorkspace();authView()}}
 if(form.id==='task-form'){if(dialog.dataset.stale)throw Error('Tugas berubah. Muat detail terbaru sebelum menyimpan.');const t=taskFromForm();if(event.submitter?.value==='email'&&t.repeat_pattern!=='once')throw Error('Simpan seri dahulu; email dikirim manual dari occurrence tertentu.');if(event.submitter?.value==='email'&&!t.pic_id)throw Error('Pilih PIC untuk email penugasan.');await api('tasks',{method:t.version?'PATCH':'POST',body:t});dialog.close();await loadTasks();render();toast(t.repeat_pattern!=='once'?'Seri tugas berulang dibuat. Gunakan tab Today untuk checklist hari ini.':conflicts(t,state.tasks).length?'Tersimpan dengan peringatan jadwal bentrok.':'Tugas tersimpan');if(event.submitter?.value==='email')await previewAssignment(t.id)}
 if(form.id==='pic-form')await savePic(f);if(form.id==='report-form'){state.reportFilters=Object.fromEntries(f);await loadReport();render()}if(form.id==='progress-form'){if(dialog.dataset.stale)throw Error('Tugas berubah. Muat detail terbaru dahulu.');await api('tasks',{method:'PATCH',body:{id:state.editing.id,version:state.editing.version,action:'progress',status:f.get('status'),progress_note:f.get('progress_note')}});dialog.close();await loadTasks();render();toast('Progres diperbarui')}
 if(form.id==='preferences-form'){await api('profile',{method:'PATCH',body:{display_name:f.get('display_name'),capacity:Number(f.get('capacity')),email_enabled:f.has('email_enabled')}});await load();toast('Preferensi tersimpan')}
 if(form.id==='password-form'){if(f.get('password')!==f.get('confirm'))throw Error('Konfirmasi password tidak sama');await api('auth',{method:'POST',body:{action:'password',password:f.get('password')}});form.reset();toast('Password diperbarui')}
 if(form.id==='invite-form'){toast((await api('users',{method:'POST',body:{action:'invite',email:f.get('email'),display_name:f.get('display_name')}})).message);accountDialog.close();await loadUsers();render()}
 if(form.id==='access-form'){if(!confirm('Simpan perubahan akses akun ini?'))return;await api('users',{method:'POST',body:{action:'access',id:form.dataset.id,role:f.get('role'),is_active:f.has('is_active')}});accountDialog.close();await loadUsers();render();toast('Akses diperbarui')}
 });});
async function boot(){
 const h=new URLSearchParams(location.hash.slice(1));const flow=new URLSearchParams(location.search).get('flow');
 // Remove invitation/recovery tokens from history before any request or navigation.
 if(location.hash)history.replaceState(null,'',location.pathname+location.search);
 if(h.get('error'))return authView('login',h.get('error_description')||'Tautan tidak valid atau kedaluwarsa.');
 if(h.get('access_token')&&h.get('refresh_token')){try{const linked=await api('auth',{method:'POST',body:{action:'accept-link',access_token:h.get('access_token'),refresh_token:h.get('refresh_token')}});return authView('password','Akun: '+linked.email)}catch(err){return authView('login',err.message)}}
 if(flow==='recovery'||flow==='invite')return authView('password','Jika tautan sudah kedaluwarsa, minta instruksi reset baru.');
 try{await load();const requested=new URLSearchParams(location.search).get('task');if(requested){const t=state.tasks.find(t=>t.id===requested);if(t)openTask(t);else toast('Tugas tidak tersedia untuk akun ini atau aksesnya telah berubah.',true);}}catch(err){clearWorkspace();authView('login',err.status===401?'':err.message)}
}
boot();

function myWork(){return state.tasks.filter(t=>t.assignee_id===state.profile.id||(t.user_id===state.profile.id&&!t.pic_id));}
function delegatedNotice(){const n=state.tasks.filter(t=>t.user_id===state.profile.id&&t.pic_id&&t.assignee_id!==state.profile.id&&t.status!=='Done').length;return n?`<div class="delegated-notice"><span>${n} tugas aktif didelegasikan. Estimasinya tidak mengurangi kapasitas pribadi Anda.</span>${act('delegated','Monitor tasks →','text-button')}</div>`:'';}
async function loadPics(){const all=[];let page=0;while(true){const d=await api('pics?page='+page);all.push(...d.pics);if(!d.hasMore)break;if(++page>1000)throw Error('Terlalu banyak PIC');}state.pics=all;}
function picOptions(value){const map=new Map();for(const p of state.pics)map.set(p.id,p.name);for(const t of state.tasks)if(t.pic_id&&!map.has(t.pic_id))map.set(t.pic_id,t.pic_name||'PIC');return[['all','Semua PIC'],['self','Pemilik tugas / tanpa PIC'],...[...map]].map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${e(l)}</option>`).join('');}
function picsPage(){return`<section class="panel"><div class="section-heading"><h2>PIC directory</h2><span class="muted">Kontak pribadi Anda</span></div><div class="user-table-wrap"><table class="user-table"><thead><tr><th>PIC</th><th>Akses tugas</th><th>Telegram</th><th>Status kontak</th><th></th></tr></thead><tbody>${state.pics.map(p=>`<tr><td><strong>${e(p.name)}</strong><small>${e(p.email)}</small></td><td>${p.linked_user_id?'Akun terhubung':'Email only'}</td><td><strong>${p.telegram_username?'@'+e(p.telegram_username):'Belum diisi'}</strong><small>${e(picConnection(p))}</small></td><td><span class="status-pill ${p.is_active?'':'off'}">${p.is_active?'Active':'Inactive'}</span></td><td><button type="button" class="secondary" data-editpic="${p.id}">Edit</button></td></tr>`).join('')}</tbody></table></div>${!state.pics.length?'<div class="empty">Tambahkan nama dan email programmer/PIC pertama Anda.</div>':''}<p class="helper">Email only tidak memberikan login. Hubungkan akun yang sudah aktif jika PIC perlu memperbarui status. Perubahan koneksi kontak berlaku pada tugas setelah pemilik menyimpan ulang tugas; email PIC yang sedang digunakan tidak dapat diganti. Nonaktif kontak membatasi penugasan baru, bukan menonaktifkan akun atau mencabut akses tugas lama.</p></section>`;}
function openPic(p={id:crypto.randomUUID(),name:'',email:'',linked_user_id:null,is_active:true}){state.editingPic=p;accountDialog.innerHTML=`<div class="dialog-header"><h2>${p.version?'Edit PIC':'New PIC'}</h2>${act('close-account','×','icon-button','aria-label="Tutup"')}</div><form id="pic-form" class="form-stack"><label>Nama PIC<input name="name" maxlength="80" value="${e(p.name)}" required></label><label>Email PIC<input name="email" type="email" maxlength="254" value="${e(p.email)}" required></label><label>Username Telegram PIC<input name="telegram_username" maxlength="33" placeholder="@username_programmer" value="${e(p.telegram_username||'')}"></label><p class="helper">PIC perlu login dan Connect personal melalui Settings. Username dicocokkan dengan akun Telegram yang melakukan pairing; username saja tidak memberikan akses.</p><label class="checkbox-label"><input type="checkbox" name="link_account" ${p.linked_user_id?'checked':''}> Hubungkan ke akun aktif dengan email yang sama</label><p class="helper">Jika akun belum ada, gunakan Email only atau minta admin mengundangnya. Memilih PIC yang terhubung saat menyimpan tugas memberikan akses detail, status, dan catatan progres.</p><label class="checkbox-label"><input type="checkbox" name="is_active" ${p.is_active?'checked':''}> Kontak aktif untuk penugasan baru</label><button class="primary">Save PIC</button></form>`;accountDialog.showModal();}
async function savePic(f){await api('pics',{method:'POST',body:{id:state.editingPic.id,version:state.editingPic.version,name:f.get('name'),email:f.get('email'),telegram_username:f.get('telegram_username'),link_account:f.has('link_account'),is_active:f.has('is_active')}});accountDialog.close();await loadPics();render();toast('PIC tersimpan. Tugas yang sudah ada tidak dibagikan ulang otomatis.');}
function updatePicHint(){const p=state.pics.find(p=>p.id===document.querySelector('#task-pic')?.value);const n=document.querySelector('#pic-hint');if(n)n.innerHTML=p?`<strong>${e(p.email)}</strong><span>${p.linked_user_id?'Akses tugas saat disimpan':'Email only · tidak memberi akses aplikasi'}</span><span>${p.telegram_username?'@'+e(p.telegram_username)+' · ':''}${e(picConnection(p))}</span>`:'<span>Anda mengerjakan tugas ini sendiri.</span>';}
function openAssignedTask(t){dialog.innerHTML=`<div class="dialog-header"><h2>Assigned task</h2>${act('close-task','×','icon-button','aria-label="Tutup"')}</div><h3>${e(t.title)}</h3><p class="helper">Dari ${e(t.owner_name||'Pemilik tugas')} · ${e(t.owner_email||'')}<br>${e(t.category)} · ${e(t.project)} · ${t.priority}<br>Deadline: ${t.due_date||'-'} · Jadwal: ${t.scheduled_date||'-'} ${t.start_time?.slice(0,5)||''} WIB · ${hours(t.duration)}</p><div class="shared-notes">${e(t.notes||'Tidak ada catatan tambahan.')}</div>${workflowPanel(t)}<p class="helper">Kriteria testing: ${e(t.acceptance_criteria||"—")}</p><form id="progress-form" class="form-stack"><label>Status<select name="status">${options(t.requires_testing?[t.status]:['To do','In progress','Done'],t.status==='Backlog'?'To do':t.status)}</select></label><label>Catatan progres<textarea name="progress_note" rows="5" maxlength="4000">${e(t.progress_note||'')}</textarea></label><p class="helper">Anda dapat memperbarui status dan progres. Rencana, deadline, PIC, dan penghapusan dikelola pemilik tugas.</p><button class="primary">Update progress</button></form>`;dialog.showModal();}
async function previewAssignment(id){const p=await api('assignments?task='+encodeURIComponent(id));state.assignmentPreview=p;accountDialog.innerHTML=`<div class="dialog-header"><h2>Review assignment email</h2>${act('close-account','×','icon-button','aria-label="Tutup"')}</div><p class="helper">Penerima: <strong>${e(p.pic_name)} &lt;${e(p.recipient)}&gt;</strong><br>Versi tugas: ${p.version}</p><h3>${e(p.subject)}</h3><pre class="email-preview">${e(p.text)}</pre><div class="setup-notice">${p.emailConfigured?'Konfigurasi email terdeteksi. Periksa alamat dan isi sebelum mengirim.':'Resend belum dikonfigurasi. Tugas sudah tersimpan; email belum dikirim.'}</div><div class="button-row">${act('assignment-send','Send assignment','primary')}${act('close-account','Cancel')}</div><p class="helper">Pengiriman sebelumnya: ${p.history.map(h=>`v${h.task_version}: ${e(h.status)} → ${e(h.recipient_email)}`).join('; ')||'Belum ada'}</p>`;accountDialog.showModal();}
async function sendAssignment(){const p=state.assignmentPreview;if(!p)return;const result=await api('assignments',{method:'POST',body:{task_id:p.task_id,version:p.version}});toast(result.message);accountDialog.close();}
const basisNames={scheduled:'Tanggal pengerjaan',due:'Deadline',completed:'Tanggal selesai (WIB)'};
const scopeNames={owned:'Tugas yang saya kelola',assigned:'Ditugaskan kepada saya',all:'Semua akses saya'};
async function loadReport(){state.report=await api('reports?'+new URLSearchParams(state.reportFilters));}
function reportsPage(){const f=state.report?.filters||state.reportFilters;const r=state.report;const select=(name,choices)=>`<select name="${name}">${Object.entries(choices).map(([v,l])=>`<option value="${v}" ${f[name]===v?'selected':''}>${l}</option>`).join('')}</select>`;return`<section class="panel report-controls"><form id="report-form"><label>Bulan<input type="month" name="month" min="2000-01" max="2099-12" value="${f.month}" required></label><label>Dasar periode${select('basis',basisNames)}</label><label>Lingkup${select('scope',scopeNames)}</label><label>Kategori<select name="category">${[['all','Semua kategori'],...CATEGORIES.map(c=>[c,c])].map(([v,l])=>`<option value="${v}" ${f.category===v?'selected':''}>${l}</option>`).join('')}</select></label><label>PIC<select name="pic">${picOptions(f.pic)}</select></label><button class="primary">Generate report</button></form></section>${r?`<div class="report-toolbar"><p>${r.filters.month} · ${basisNames[r.filters.basis]} · ${scopeNames[r.filters.scope]}</p><div class="button-row">${act('report-xlsx','↓ Excel (.xlsx)')}${act('report-csv','↓ CSV')}${act('report-print','Print / PDF')}</div></div><p class="helper">Status dan PIC mengikuti data saat laporan dibuat, bukan arsip kondisi akhir bulan. Ekspor mengambil data terbaru dengan filter hasil terakhir; klik Generate setelah mengubah filter. Estimasi bukan jam kerja aktual.</p><div class="stats"><div class="stat"><span>Tasks in period</span><div>${r.summary.total}</div></div><div class="stat"><span>Done now</span><div>${r.summary.done}</div></div><div class="stat"><span>In progress now</span><div>${r.summary.inProgress}</div></div><div class="stat"><span>Estimated work</span><div>${hours(r.summary.minutes)}</div></div></div><section class="panel"><h2>Summary by PIC</h2><div class="user-table-wrap"><table class="user-table"><thead><tr><th>PIC</th><th>Tasks</th><th>Done now</th><th>Estimated minutes</th></tr></thead><tbody>${r.summary.byPic.map(g=>`<tr><td>${e(g.name)}<small>${e(g.email)}</small></td><td>${g.tasks}</td><td>${g.done}</td><td>${g.minutes}</td></tr>`).join('')}</tbody></table></div></section><section class="panel" style="margin-top:22px"><h2>Task details</h2><div class="user-table-wrap"><table class="user-table"><thead><tr><th>Task / project</th><th>PIC</th><th>Current status</th><th>Deadline</th><th>Minutes</th></tr></thead><tbody>${r.rows.map(t=>`<tr><td>${e(t.title)}<small>${e(t.project)}</small></td><td>${e(t.pic_name||t.owner_name||'Pemilik tugas')}</td><td>${t.status}</td><td>${t.due_date||'-'}</td><td>${t.duration}</td></tr>`).join('')}</tbody></table></div>${!r.rows.length?'<p class="no-data">Tidak ada tugas pada periode/filter ini. File ekspor tetap memuat header dan ringkasan nol.</p>':''}</section>`:'<p class="helper">Pilih periode lalu Generate report.</p>'}`;}
async function downloadReport(format){if(!state.report)return;const q=new URLSearchParams({...state.report.filters,format});const response=await fetch('/api/reports?'+q,{credentials:'same-origin',cache:'no-store'});if(!response.ok){const err=await response.json();throw Error(err.error||'Ekspor gagal')}const blob=await response.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`focusdesk-${state.report.filters.month}-${state.report.filters.basis}.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Laporan diunduh.');}
function printReport(){const r=state.report;if(!r)return;let area=document.querySelector('#print-report');if(!area){area=document.createElement('section');area.id='print-report';document.body.append(area)}const picLabel=r.filters.pic==='all'?'Semua PIC':r.filters.pic==='self'?'Pemilik tugas':r.summary.byPic[0]?.name||'PIC terpilih';area.innerHTML=`<h1>Monthly work report</h1><p>Focusdesk · ${e(r.owner)}<br>Periode: ${r.filters.month} · ${basisNames[r.filters.basis]}<br>${scopeNames[r.filters.scope]} · Kategori: ${e(r.filters.category)} · PIC: ${e(picLabel)}<br>Dibuat: ${new Date(r.generatedAt).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})} WIB</p><p>${r.summary.total} tugas · ${r.summary.done} Done sekarang · ${r.summary.inProgress} In progress · ${r.summary.minutes} menit estimasi.</p><p class="report-definition">Status/PIC saat laporan dibuat. Ini bukan arsip status akhir bulan atau pencatatan jam kerja aktual.</p><h2>Summary by PIC</h2><table><thead><tr><th>PIC</th><th>Tasks</th><th>Done now</th><th>Minutes</th></tr></thead><tbody>${r.summary.byPic.map(g=>`<tr><td>${e(g.name)}<br>${e(g.email)}</td><td>${g.tasks}</td><td>${g.done}</td><td>${g.minutes}</td></tr>`).join('')}</tbody></table><h2>Task details</h2><table><thead><tr><th>Task / project</th><th>PIC</th><th>Status</th><th>Deadline</th><th>Minutes</th></tr></thead><tbody>${r.rows.map(t=>`<tr><td>${e(t.title)}<br><small>${e(t.project)}</small></td><td>${e(t.pic_name||t.owner_name||'Pemilik tugas')}</td><td>${t.status}</td><td>${t.due_date||'-'}</td><td>${t.duration}</td></tr>`).join('')}</tbody></table>`;window.print();}
function testingFields(t){return `<fieldset class="repeat-controls"><legend>Telegram & review</legend><label class="checkbox-label"><input type="checkbox" name="requires_testing" ${t.requires_testing?'checked disabled':''}> Wajib testing oleh saya (pemilik tugas)</label><p class="helper">PIC tidak dapat menutup tugas testing. Setelah aktif, aturan testing tidak dapat dimatikan untuk melewati review.</p><label>Kriteria kelulusan<textarea name="acceptance_criteria" maxlength="4000" rows="2">${e(t.acceptance_criteria||'')}</textarea></label><label>Bagikan ke grup Telegram<select name="telegram_group_id"><option value="">Tidak dibagikan ke grup</option>${(state.telegram?.groups||[]).filter(g=>g.active||g.id===t.telegram_group_id).map(g=>`<option value="${g.id}" ${g.id===t.telegram_group_id?'selected':''}>${e(g.title)}${g.active?'':' (nonaktif)'}</option>`).join('')}</select></label><p class="helper">Semua anggota grup dapat membaca judul, PIC, jadwal, progres dan kriteria test. Notes internal tidak dikirim. Tombol tindakan hanya ada di chat pribadi PIC/reviewer yang terhubung. Grup menerima notifikasi tanpa tombol tindakan.</p></fieldset>`;}
function workflowPanel(t){if(!t.version)return '';return `<section class="workflow-panel"><strong>${e(t.status)}${t.requires_testing?' · Test cycle '+t.test_cycle:''}</strong><p class="helper">${t.requires_testing?'Pemilik tugas adalah reviewer. Gunakan tombol di bawah untuk transisi status.':'Perbarui progres atau status pengerjaan.'}</p><div class="button-row">${actions(t,roleFor(t,state.profile.id).owner,roleFor(t,state.profile.id).executor).map(([a,l])=>`<button type="button" class="secondary" data-wf="${a}">${l}</button>`).join('')}<button type="button" class="text-button" data-wf="history">Activity history</button></div></section>`;}
function telegramPanel(){const tg=state.telegram||{};return `<section class="panel telegram-panel"><h2>Telegram · Focusdesk v1.6</h2><span class="status-pill ${tg.configured?'':'off'}">${tg.configured?'Token dikonfigurasi':'Token belum diatur'}</span><p class="helper">${tg.account?'Terhubung: '+(tg.account.telegram_username?'@'+e(tg.account.telegram_username)+' · ':'')+'Telegram ID '+e(tg.account.telegram_id):'Hubungkan akun Anda menggunakan kode sekali pakai, berlaku 10 menit.'}</p><div class="button-row"><button class="secondary" data-tg="personal">Connect personal</button>${tg.account?'<button class="text-button danger" data-tg="disconnect">Disconnect personal</button>':''}<button class="secondary" data-tg="group">Connect group</button></div><div id="telegram-code" class="setup-notice" hidden></div><div class="setup-notice"><strong>Scheduler · Asia/Jakarta</strong><p>Setiap hari, termasuk Sabtu–Minggu · 09.00 &amp; 17.30 WIB</p><p class="helper">Panggilan terakhir: ${tg.scheduler?.last_tick_at?e(new Date(tg.scheduler.last_tick_at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})):'Belum tercatat; periksa aktivasi scheduler'}. Ini bukti pemanggilan terakhir, bukan jaminan job masih aktif.</p><p class="helper">Grup hanya merangkum tugas yang dibagikan kepadanya. Kartu pagi dikirim bertahap setelah ringkasan grup diproses. Refresh untuk memperbarui riwayat.</p></div><h3>Grup saya</h3>${(tg.groups||[]).map(g=>`<p>${e(g.title)} · ${g.active?'Aktif':'Nonaktif'} ${g.active?`<button class="text-button danger" data-tg="disconnect-group" data-group="${g.id}">Disconnect</button>`:''}</p>`).join('')||'<p class="helper">Belum ada grup. Pilih grup secara eksplisit pada setiap tugas.</p>'}<div class="button-row"><button class="secondary" data-tg="daily">Send personal briefing</button><button class="secondary" data-tg="drain">Process pending queue</button></div>${state.profile.role==='admin'?'<h3>Admin setup</h3><div class="button-row"><button class="secondary" data-tg="webhook">Register webhook</button><button class="text-button" data-tg="webhook-status">Check webhook</button></div>':''}<p class="helper">09.00 WIB: ringkasan grup + kartu DM sesuai PIC/reviewer. 17.30 WIB: tugas tertunda, hari ini belum selesai, dan agenda besok di grup. Aktifkan Supabase Cron sesuai README v1.5; Vercel Hobby bukan jadwal menit-presisi. Tombol lama ditolak setelah tugas berubah; ketik /tasks untuk kartu terbaru. Riwayat di bawah milik tugas/antrean yang Anda kelola.</p><details><summary>Riwayat pengiriman terbaru</summary>${(tg.history||[]).map(h=>`<p>${e(h.kind)}${h.schedule_slot?' / '+e(h.schedule_slot):''}${h.day?' · '+e(h.day):''} · ${e(h.status)} · ${h.attempts} percobaan<br><small>${e(h.last_error||'')} ${e(h.created_at)}</small></p>`).join('')||'<p>Belum ada pengiriman.</p>'}</details></section>`;}
document.addEventListener('click',event=>{
 const n=event.target.closest('[data-tg],[data-wf]');if(!n||n.disabled)return;
 void work(async()=>{
  if(n.dataset.wf){if(dialog.dataset.stale&&n.dataset.wf!=='history')throw Error('Muat detail terbaru dahulu.');const t=state.editing,a=n.dataset.wf;if(!t)return;
   if(a==='history'){const d=await api('tasks?activity='+t.id);accountDialog.innerHTML=`<div class="dialog-header"><h2>Activity history</h2>${act('close-account','×','icon-button')}</div>${d.activity.map(x=>`<p><strong>${e(x.from_status||'Created')} → ${e(x.to_status)}</strong> · Cycle ${x.test_cycle}<br>${e(x.note)}<br><small>${e(x.created_at)} · actor ${e(x.actor_id||'system')}</small></p>`).join('')||'<p>Riwayat tersedia sejak upgrade v1.3.</p>'}`;accountDialog.showModal();return;}
   let note=t.progress_note||'';if(a==='fail'){note=prompt('Alasan pengembalian / hasil testing yang gagal (wajib):','');if(note===null)return;if(!note.trim())throw Error('Alasan wajib diisi.');}
   await api('tasks',{method:'PATCH',body:{id:t.id,version:t.version,action:'progress',status:actionStatus[a],progress_note:note}});dialog.close();await loadTasks();render();toast('Status diperbarui; notifikasi masuk antrean.');return;
  }
  const a=n.dataset.tg;
  if(a==='personal'||a==='group'){
   const d=await api('telegram',{method:'POST',body:{action:'code',kind:a}}),el=document.querySelector('#telegram-code');el.hidden=false;
   const command=(a==='personal'?'/start ':'/connect@'+(state.telegram.botUsername||'BOT_USERNAME')+' ')+d.code;
   el.innerHTML=`<strong>Kode berlaku 10 menit. Jangan bagikan kode personal.</strong><p>Kirim ke ${a==='personal'?'chat pribadi bot':'grup, dari akun Telegram Anda yang sudah terhubung dan menjadi admin grup'}:</p><code>${e(command)}</code>${a==='personal'&&/^[A-Za-z0-9_]+$/.test(state.telegram.botUsername||'')?`<p><a href="https://t.me/${e(state.telegram.botUsername)}?start=${d.code}" target="_blank" rel="noopener noreferrer">Open Telegram bot ↗</a></p>`:''}<p>Setelah berhasil, tekan ↻ untuk memuat koneksi.</p>`;return;
  }
  if(a.startsWith('disconnect')&&!confirm('Putus koneksi ini? Pesan yang sudah terkirim tetap berada di Telegram.'))return;
  const d=await api('telegram',{method:'POST',body:{action:a.startsWith('disconnect')?'disconnect':a,group_id:n.dataset.group||null}});toast(d.message);state.telegram=await api('telegram');render();
 });
});

import {taskSnapshot,fetchTasks} from './sync.js';
